  async Task<bool> BuildCandidate(CADDocument candidate,bool record,bool fit=false,int? previewMarker=null,bool commit=true){if(busy||disposed)return false;busy=true;message.Text="CAD-ядро: построение…";int ticket=++revision;string before=Document.Serialize();try{candidate.Validate();var result=await Task.Factory.StartNew(()=>kernel.Run(candidate,"build",null,null,previewMarker));if(disposed||ticket!=revision)return false;if(commit){if(record&&before!=candidate.Serialize()){undo.Push(before);redo.Clear();}Document=candidate;marker=previewMarker??Document.Features.Count;}Render(candidate,result,fit||State==null||result.Bodies.Count>(State.Bodies==null?0:State.Bodies.Count));if(commit){BuildBrowser();UpdateTitle();}message.Text=(result.Bodies??new List<CADBody>()).Count+" тел · STEP B-rep · "+(previewMarker.HasValue?"история: "+previewMarker:"модель актуальна");return true;}catch(Exception ex){if(!disposed){message.Text="Изменение не применено";ShowError(ex);}return false;}finally{busy=false;}}

  void Render(CADDocument doc,CADKernelResult result,bool fit){State=result;restoreCamera=!fit&&Scene.Ready;if(restoreCamera){cameraTarget=Scene.Camera.Target;cameraWidth=Scene.Camera.Width;cameraYaw=Scene.Camera.Yaw;cameraPitch=Scene.Camera.Pitch;}Scene.ResetPlacements();var model=result.Assembly(doc);Scene.SetResult(model.Parts.Count==0?null:new Result{P=new Parameters{Kind=9},Model=model},true);if(!result.Bodies.Any(b=>b.Id==selectedBody)){selectedBody=result.Bodies.Select(b=>b.Id).FirstOrDefault();if(selectedBody!=null)selectedFeature=null;pickedFaces.Clear();pickedEdges.Clear();}FillInspector();RefreshAdorners();RefreshSketchDisplay(doc,result,marker);if(fit)Scene.Fit();}

  void BuildBrowser(){updating=true;try{browser.BeginUpdate();browser.Nodes.Clear();var root=browser.Nodes.Add(Document.Name);var origin=root.Nodes.Add("Начало координат");origin.Nodes.Add("XY");origin.Nodes.Add("XZ");origin.Nodes.Add("YZ");var bodies=root.Nodes.Add("Тела");foreach(var b in State==null?new List<CADBody>():State.Bodies){var n=bodies.Nodes.Add(CADTools.BodyName(Document,b.Id));n.Tag="b:"+b.Id;n.Checked=!Document.Hidden.Contains(b.Id);}var sketches=root.Nodes.Add("Эскизы");foreach(var f in Document.Features.Where(f=>f.Kind=="sketch")){var n=sketches.Nodes.Add(f.Name+(f.Suppressed?" · подавлен":""));n.Tag="f:"+f.Id;n.Checked=!f.Suppressed&&!Document.Hidden.Contains(f.Id);}var history=root.Nodes.Add("Операции");foreach(var f in Document.Features){var n=history.Nodes.Add(f.Name+(f.Suppressed?" · подавлена":""));n.Tag="f:"+f.Id;}root.Expand();bodies.Expand();sketches.Expand();browser.EndUpdate();timeline.Controls.Clear();for(int i=0;i<Document.Features.Count;i++){var f=Document.Features[i];var b=new Button{Text=(i+1)+"\n"+f.Name,Width=105,Height=58,FlatStyle=FlatStyle.Flat,BackColor=i<marker?(f.Suppressed?Color.Gainsboro:Color.White):Color.FromArgb(216,223,232),Tag=f.Id};b.Click+=(s,e)=>{selectedFeature=(string)((Button)s).Tag;FillInspector();};b.DoubleClick+=(s,e)=>EditFeature((string)((Button)s).Tag);var cm=new ContextMenuStrip();cm.Items.Add("Изменить…",null,(s,e)=>EditFeature(f.Id));cm.Items.Add("Подавить / включить",null,(s,e)=>{selectedFeature=f.Id;Suppress();});cm.Items.Add("Удалить",null,(s,e)=>{selectedFeature=f.Id;RemoveFeature();});b.ContextMenuStrip=cm;timeline.Controls.Add(b);}historyInfo.Text="История: "+marker+" / "+Document.Features.Count;}finally{updating=false;}}

  void Visibility(){if(!Scene.Ready)return;Scene.Hidden.Clear();foreach(var id in Document.Hidden)Scene.Hidden.Add(id);Scene.RefreshVisibility();}

  void SelectBody(string id,bool clear=true){if(Body==null||selectedBody!=id){pickedFaces.Clear();pickedEdges.Clear();}selectedBody=id;selectedFeature=null;if(clear){pickedFaces.Clear();pickedEdges.Clear();}Scene.Select(id);FillInspector();RefreshAdorners();}

  void PickedTriangle(string id,int vertex){if(id==null||State==null)return;var b=State.Bodies.FirstOrDefault(x=>x.Id==id);if(b==null||vertex<0)return;selectedBody=id;if(measuring){if(!measuredFirst.HasValue){measuredFirst=Scene.LastPickPoint;message.Text="Выберите вторую точку.";}else{message.Text="Расстояние: "+Engine.F((Scene.LastPickPoint-measuredFirst.Value).Length)+" мм";measuring=false;}return;}int triangle=vertex/3;if(triangle>=b.TriangleFaces.Length)return;bool add=(ModifierKeys&Keys.Control)!=0;if(selectionMode.SelectedIndex==2){int edge=NearestEdge(b,Scene.LastPickPoint);if(edge<0){message.Text="Нажмите ближе к ребру или выберите его в списке справа.";return;}if(!add)pickedEdges.Clear();if(pickedEdges.Contains(edge))pickedEdges.Remove(edge);else pickedEdges.Add(edge);pickedFaces.Clear();}else{int face=b.TriangleFaces[triangle];if(!add)pickedFaces.Clear();if(pickedFaces.Contains(face))pickedFaces.Remove(face);else pickedFaces.Add(face);pickedEdges.Clear();}FillInspector();RefreshAdorners();}

  int NearestEdge(CADBody b,Point3D p){double best=Scene.Camera.Width/Math.Max(1,Scene.Root.ActualWidth)*14;int found=-1;foreach(var edge in b.Edges)for(int i=1;i<edge.Points.Length;i++){var a=new Point3D(edge.Points[i-1][0],edge.Points[i-1][1],edge.Points[i-1][2]);var c=new Point3D(edge.Points[i][0],edge.Points[i][1],edge.Points[i][2]);var d=c-a;double t=Math.Max(0,Math.Min(1,Vector3D.DotProduct(p-a,d)/Math.Max(1e-12,d.LengthSquared)));double distance=(p-(a+d*t)).Length;if(distance<best){best=distance;found=edge.Id;}}return found;}

  void FillInspector(){if(editingSketch!=null){FillSketchInspector();return;}inspector.Controls.Clear();var flow=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(10)};inspector.Controls.Add(flow);var feature=Document.Features.FirstOrDefault(f=>f.Id==selectedFeature);if(feature!=null){flow.Controls.Add(Label(feature.Name+"\n"+CADTools.Name(feature.Kind),65));AddAction(flow,"Изменить операцию…",()=>EditFeature(feature.Id));if(feature.Kind=="sketch"&&!feature.Suppressed)AddAction(flow,"Выдавить этот эскиз",()=>Operation("extrude"));AddAction(flow,feature.Suppressed?"Включить":"Подавить",Suppress);AddAction(flow,"Удалить из истории",RemoveFeature);foreach(var p in feature.Values)flow.Controls.Add(Label(CADTools.Field(p.Key)+": "+p.Value,35));return;}var b=Body;if(b==null){flow.Controls.Add(Label("Создайте эскиз, примитив или импортируйте STEP.\n\nНачните с «Эскиз» → нарисуйте контур → «Завершить эскиз» → «Выдавливание».",160));return;}CADMaterial material;if(!Document.Materials.TryGetValue(b.Id,out material))material=new CADMaterial();var bounds=b.Bounds;flow.Controls.Add(Label(CADTools.BodyName(Document,b.Id)+"\n"+Engine.F(bounds[3]-bounds[0])+" × "+Engine.F(bounds[4]-bounds[1])+" × "+Engine.F(bounds[5]-bounds[2])+" мм\nОбъём: "+Engine.F(b.Volume)+" мм³\nМасса: "+Engine.F(b.Volume*material.Density*1e-9)+" кг · "+material.Name,112));AddAction(flow,"Материал и цвет…",Material);if(pickedFaces.Count>0){var f=b.Faces.FirstOrDefault(x=>x.Id==pickedFaces.Last());if(f!=null){flow.Controls.Add(Label(f+"\nПлощадь: "+Engine.F(f.Area)+" мм²"+(f.Radius>0?"\nR "+Engine.F(f.Radius)+" мм":""),78));AddAction(flow,"Эскиз на выбранной грани",()=>BeginSketch(null));AddAction(flow,"Нажать / вытянуть (Q)",()=>Operation("presspull"));AddAction(flow,"Отверстие",()=>Operation("hole"));}}if(pickedEdges.Count>0){flow.Controls.Add(Label("Выбрано рёбер: "+pickedEdges.Count+"\nДлина: "+Engine.F(b.Edges.Where(x=>pickedEdges.Contains(x.Id)).Sum(x=>x.Length))+" мм",58));AddAction(flow,"Скругление (F)",()=>Operation("fillet"));AddAction(flow,"Фаска",()=>Operation("chamfer"));}var choose=new EditorComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList};choose.Items.Add("Выбрать грань / ребро из списка");foreach(var f in b.Faces)choose.Items.Add(f);foreach(var edge in b.Edges)choose.Items.Add(edge);choose.SelectedIndex=0;choose.SelectedIndexChanged+=(s,e)=>{pickedFaces.Clear();pickedEdges.Clear();if(choose.SelectedItem is CADFace){var face=(CADFace)choose.SelectedItem;pickedFaces.Add(face.Id);Scene.LastPickPoint=new Point3D(face.Center[0],face.Center[1],face.Center[2]);}if(choose.SelectedItem is CADEdge)pickedEdges.Add(((CADEdge)choose.SelectedItem).Id);FillInspector();RefreshAdorners();};flow.Controls.Add(choose);flow.Controls.Add(Label("Ctrl+щелчок — несколько граней или рёбер. Цветные оси в сцене перемещают тело. Поворот и копирование — клавиша M.",100));}

  static Label Label(string text,int height){return new Label{Text=text,Width=280,Height=height,Margin=new Padding(0,6,0,4)};}static void AddAction(Control panel,string title,Action action){var b=new Button{Text=title,Width=280,Height=34,Margin=new Padding(0,3,0,3)};b.Click+=(s,e)=>action();panel.Controls.Add(b);}

  async void Operation(string kind){if(busy||editingSketch!=null)return;var feature=CADTools.Feature(kind);feature.Target=selectedBody;feature.Faces=pickedFaces.ToList();feature.Edges=pickedEdges.ToList();if(kind=="hole"&&pickedFaces.Count>0)feature.Point=new[]{Scene.LastPickPoint.X,Scene.LastPickPoint.Y,Scene.LastPickPoint.Z};if(new[]{"extrude","revolve","loft","sweep"}.Contains(kind)){var sk=Document.Features.Where(f=>f.Kind=="sketch"&&!f.Suppressed).ToList();if(selectedFeature!=null&&sk.Any(f=>f.Id==selectedFeature)&&kind!="loft"&&kind!="sweep")sk=new System.Collections.Generic.List<CADFeature>{sk.First(f=>f.Id==selectedFeature)};feature.Sketches=kind=="loft"||kind=="sweep"?sk.Select(f=>f.Id).TakeLastCompat(2).ToList():sk.Select(f=>f.Id).TakeLastCompat(1).ToList();}var snapshot=Document.Clone();var current=State??new CADKernelResult{Bodies=new List<CADBody>()};using(var dialog=new CADOperationDialog(Document,current,feature)){dialog.Preview+=async f=>{var trial=snapshot.Clone();trial.Features.Insert(Math.Min(marker,trial.Features.Count),f);return await BuildCandidate(trial,false,false,null,false);};if(dialog.ShowLocalizedDialog(this)==DialogResult.OK){var next=snapshot.Clone();next.Features.Insert(Math.Min(marker,next.Features.Count),dialog.Feature);if(!await BuildCandidate(next,true)){await BuildCandidate(snapshot,false);}}else await BuildCandidate(snapshot,false);}}

  async void EditFeature(string id){if(busy||editingSketch!=null)return;int index=Document.Features.FindIndex(f=>f.Id==id);if(index<0)return;var feature=Document.Features[index];if(feature.Kind=="sketch"){BeginSketch(feature);return;}if(feature.Kind=="import"){UiMessage.Show(this,"Импорт хранится в проекте. Выберите грань и используйте прямые операции; исходный STEP не содержит истории автора.");return;}var snapshot=Document.Clone();try{busy=true;var pre=await Task.Factory.StartNew(()=>kernel.Run(snapshot,"build",null,null,index));busy=false;using(var dialog=new CADOperationDialog(snapshot,pre,feature)){dialog.Preview+=async f=>{var trial=snapshot.Clone();trial.Features[index]=f;return await BuildCandidate(trial,false,false,null,false);};if(dialog.ShowLocalizedDialog(this)==DialogResult.OK){var trial=snapshot.Clone();trial.Features[index]=dialog.Feature;if(!await BuildCandidate(trial,true))await BuildCandidate(snapshot,false);}else await BuildCandidate(snapshot,false);}}catch(Exception ex){busy=false;ShowError(ex);}}

  async void Suppress(){if(busy||selectedFeature==null)return;var trial=Document.Clone();var f=trial.Features.FirstOrDefault(x=>x.Id==selectedFeature);if(f==null)return;f.Suppressed=!f.Suppressed;await BuildCandidate(trial,true);}

  async void RemoveFeature(){if(busy||selectedFeature==null)return;var trial=Document.Clone();trial.Features.RemoveAll(f=>f.Id==selectedFeature);await BuildCandidate(trial,true);}

  async void Roll(int step){if(busy||editingSketch!=null)return;step=Math.Max(0,Math.Min(Document.Features.Count,step));await BuildCandidate(Document.Clone(),false,false,step);}

  async void CommitMove(string id,Vector3D delta){if(busy)return;var f=CADTools.Feature("move");f.Target=id;f.Values["X"]=Engine.N(AppSettings.Snap(delta.X));f.Values["Y"]=Engine.N(AppSettings.Snap(delta.Y));f.Values["Z"]=Engine.N(AppSettings.Snap(delta.Z));var trial=Document.Clone();trial.Features.Add(f);if(!await BuildCandidate(trial,true)){Scene.ResetPlacements();RefreshAdorners();}}

  async void Undo(){if(busy||undo.Count==0||editingSketch!=null)return;string previous=undo.Pop();string current=Document.Serialize();if(await BuildCandidate(CADDocument.Parse(previous),false))redo.Push(current);else undo.Push(previous);}async void Redo(){if(busy||redo.Count==0||editingSketch!=null)return;string next=redo.Pop();string current=Document.Serialize();if(await BuildCandidate(CADDocument.Parse(next),false))undo.Push(current);else redo.Push(next);}

  async void Parameters(){if(busy)return;using(var dialog=new CADParametersDialog(Document.Parameters))if(dialog.ShowLocalizedDialog(this)==DialogResult.OK){var next=Document.Clone();next.Parameters=dialog.Values;await BuildCandidate(next,true);}}

  void UpdateTitle(){Text="GearLab 6.8.0 · "+Document.Name+(Document.Serialize()!=saved||editingSketch!=null?" *":"");}

  bool Confirm(){if(busy){UiMessage.Show(this,"Дождитесь расчёта или отмените его.");return false;}if(editingSketch!=null){UiMessage.Show(this,"Завершите или отмените текущий эскиз.");return false;}if(Document.Serialize()==saved)return true;var answer=UiMessage.Show(this,"Сохранить CAD-проект?","CAD-проект",MessageBoxButtons.YesNoCancel);return answer==DialogResult.No||(answer==DialogResult.Yes&&Save(false));}

  async void Replace(CADDocument next,string file){if(!Confirm())return;var old=Document;Document=next;path=file;selectedBody=null;selectedFeature=null;undo.Clear();redo.Clear();saved=next.Serialize();marker=next.Features.Count;if(!await BuildCandidate(next,false,true)){Document=old;BuildBrowser();}}

  void Open(){if(busy)return;using(var dialog=new OpenFileDialog{Filter="CAD-проект GearLab|*.cad.json|STEP|*.step;*.stp"})if(dialog.ShowLocalizedDialog(this)==DialogResult.OK)try{if(dialog.FileName.EndsWith(".cad.json",StringComparison.OrdinalIgnoreCase))Replace(CADDocument.Parse(File.ReadAllText(dialog.FileName)),dialog.FileName);else Replace(CADDocument.ImportStep(File.ReadAllBytes(dialog.FileName),Path.GetFileNameWithoutExtension(dialog.FileName)),null);}catch(Exception ex){ShowError(ex);}}

  bool Save(bool choose){if(editingSketch!=null){UiMessage.Show(this,"Сначала завершите эскиз.");return false;}try{string file=path;if(choose||file==null)using(var dialog=new SaveFileDialog{Filter="CAD-проект с историей|*.cad.json",FileName=Document.Name+".cad.json"}){if(dialog.ShowLocalizedDialog(this)!=DialogResult.OK)return false;file=dialog.FileName;}Document.Save(file);path=file;saved=Document.Serialize();UpdateTitle();return true;}catch(Exception ex){ShowError(ex);return false;}}

  async void ImportStep(){if(busy)return;using(var dialog=new OpenFileDialog{Filter="CAD STEP|*.step;*.stp"})if(dialog.ShowLocalizedDialog(this)==DialogResult.OK)try{var feature=new CADFeature{Kind="import",Name=Path.GetFileNameWithoutExtension(dialog.FileName),Data=Convert.ToBase64String(File.ReadAllBytes(dialog.FileName))};var next=Document.Clone();next.Features.Add(feature);await BuildCandidate(next,true,true);}catch(Exception ex){ShowError(ex);}}

  async void Export(string mode){if(busy||State==null||State.Bodies.Count==0||editingSketch!=null)return;using(var dialog=new SaveFileDialog{Filter=mode=="export_step"?"STEP — точные CAD-тела|*.step":"STL — печатная сетка|*.stl",FileName=Document.Name+(mode=="export_step"?".step":".stl")})if(dialog.ShowLocalizedDialog(this)==DialogResult.OK){busy=true;try{var result=await Task.Factory.StartNew(()=>kernel.Run(Document,mode,dialog.FileName));message.Text="Сохранено: "+result.Path;}catch(Exception ex){ShowError(ex);}finally{busy=false;}}}

  async void ApplyNative(){if(apply==null||busy||State==null)return;if(State.Bodies.Count!=1){UiMessage.Show(this,"Для замены одной детали объедините результат в одно тело.");return;}busy=true;try{var result=await Task.Factory.StartNew(()=>kernel.Run(Document,"native",null,State.Bodies[0].Id));var body=result.Bodies[0];body.ReadMesh();var mesh=MeshDocument.FromScene(body.Display,Document.Name);if(apply(new CADNative{Project=Document.Serialize(),Step=result.Step,Preview=CADMeshCodec.Encode(body.Display),Mesh=mesh,Volume=body.Volume,Center=body.Center,Parameters=result.Parameters})){allowClose=true;Close();}}catch(Exception ex){ShowError(ex);}finally{busy=false;}}

  void ShowError(Exception ex){UiMessage.Show(this,ex.GetBaseException().Message,"Операция не применена",MessageBoxButtons.OK,MessageBoxIcon.Information);}

  void Help(){UiMessage.Show(this,"ЭСКИЗ → ТЕЛО\nСоздайте эскиз на XY/XZ/YZ или выбранной плоской грани. Рисуйте контуры мышью; размеры и связи — справа. Завершите эскиз и выберите выдавливание, вращение, лофт или протяжку.\n\nИЗМЕНЕНИЕ\nВыберите грань или ребро; Ctrl добавляет элементы. Q — нажать/вытянуть, F — скругление, M — перемещение. Кнопки Изменить предлагают отверстие, фаску, оболочку, объединение, разделение, массивы и зеркало. Цветные оси перемещают тело мышью.\n\nИСТОРИЯ\nОперации находятся внизу. Выберите операцию → Изменить; контекстное меню также позволяет подавить её. Стрелки показывают промежуточные стадии. Параметры и формулы пересчитывают историю.\n\nИмпорт STEP редактируется как CAD-тело. Исходная история Fusion в STEP не передаётся. Ctrl+S сохраняет .cad.json с собственной историей GearLab.\n\nЭто самостоятельный CAD-редактор на Open CASCADE. CAM, PCB, FEA и полный набор функций Fusion в него не входят.","CAD Studio");}

  internal void ApproveTestClose(){allowClose=true;}

  protected override void Dispose(bool disposing){if(disposing&&!disposed){disposed=true;revision++;recovery.Dispose();kernel.Dispose();Scene.Dispose();host.Child=null;}base.Dispose(disposing);}

 }

 static class CADEnumerable {public static IEnumerable<T> TakeLastCompat<T>(this IEnumerable<T> items,int count){var a=items.ToArray();return a.Skip(Math.Max(0,a.Length-count));}}

}







